function maximumsSplicedArray(nums1, nums2) {
  let sum1 = 0;
  let sum2 = 0;
  for (let i = 0; i < nums1.length; i++) {
    sum1 += nums1[i];
    sum2 += nums2[i];
  }

  const bestGain = (keep, take) => {
    let dp = 0;
    let best = 0;
    for (let i = 0; i < keep.length; i++) {
      dp = Math.max(0, dp + take[i] - keep[i]);
      best = Math.max(best, dp);
    }
    return best;
  };

  const score1 = sum1 + bestGain(nums1, nums2);
  const score2 = sum2 + bestGain(nums2, nums1);
  return Math.max(score1, score2);
}

