function maximumsSplicedArray(nums1, nums2) {
  // Try every block (and no swap), rebuilding both totals each time.
  const n = nums1.length;
  const total = arr => arr.reduce((a, b) => a + b, 0);
  let best = Math.max(total(nums1), total(nums2));
  for (let l = 0; l < n; l++) {
    for (let r = l; r < n; r++) {
      let a = 0, b = 0;
      for (let k = 0; k < n; k++) {
        const swapped = k >= l && k <= r;
        a += swapped ? nums2[k] : nums1[k];
        b += swapped ? nums1[k] : nums2[k];
      }
      best = Math.max(best, a, b);
    }
  }
  return best;
}

