function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const top = size === 'large' || rand() < 0.3 ? 10000 : 1 + Math.floor(rand() * 12);
  const value = () => 1 + Math.floor(rand() * top);
  const nums1 = Array.from({ length: n }, value);
  const nums2 = Array.from({ length: n }, value);
  return [nums1, nums2];
}
